//! Cargo-driven `oleaut32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is oleaut32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x7a050000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ffa1000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ffa1000000u64)),
        o => panic!("oleaut32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/oleaut32/oleaut32_ocidl_r.o", "dll/win32/oleaut32/oleaut32_oaidl_r.o", "body", "engine:wine", "engine:c:wineldr", "engine:uuid", "engine:pseh", "engine:oldnames", "import:comctl32", "import:urlmon", "import:windowscodecs", "import:ole32", "import:rpcrt4", "import:user32", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust"],
        "x86_64" => &["dll/win32/oleaut32/oleaut32_ocidl_r.o", "dll/win32/oleaut32/oleaut32_oaidl_r.o", "body", "engine:wine", "engine:c:wineldr", "engine:uuid", "engine:pseh", "engine:oldnames", "import:comctl32", "import:urlmon", "import:windowscodecs", "import:ole32", "import:rpcrt4", "import:user32", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["dll/win32/oleaut32/oleaut32_ocidl_r.o", "dll/win32/oleaut32/oleaut32_oaidl_r.o", "body", "engine:wine", "engine:c:wineldr", "engine:uuid", "engine:pseh", "engine:oldnames", "import:comctl32", "import:urlmon", "import:windowscodecs", "import:ole32", "import:rpcrt4", "import:user32", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/oleaut32",
        "dll/win32/oleaut32",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "ENTRY_PREFIX=OLEAUTPS_",
        "PROXY_CLSID=CLSID_PSFactoryBuffer",
        "PROXY_DELEGATION",
        "WINE_REGISTER_DLL",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_OLEAUT32_",
        "_WIN32_WINNT=0x600",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("oleaut32-rust")
        .c_from_compile_db("oleaut32_shims", &["dll/win32/oleaut32/proxy.dlldata.c", "dll/win32/oleaut32/oleaut32_oaidl_p.c", "dll/win32/oleaut32/oleaut32_ocidl_p.c"])
        .rc("dll/win32/oleaut32/oleaut32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .delay_import_lib("dll/win32/urlmon/urlmon.spec", "urlmon.dll", "urlmon")
        .delay_import_lib("dll/win32/windowscodecs/windowscodecs.spec", "windowscodecs.dll", "windowscodecs")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
